import CryptoKit
import Foundation
import Testing
@testable import PalmCore

/// Holds the vendored libjpeg-turbo to the bytes `djpeg` produces. Android decodes with libjpeg-turbo,
/// and the detector's parity with Android depends on this equality. JPEGFixtures.swift is generated by
/// Scripts/make-jpeg-fixtures.py from synthetic images.
struct JPEGDecoderTests {
    private func sha256(_ bytes: [UInt8]) -> String {
        SHA256.hash(data: bytes).map { String(format: "%02x", $0) }.joined()
    }

    @Test(arguments: jpegFixtures)
    func decodeMatchesDjpeg(_ fixture: JPEGFixture) throws {
        let jpeg = try #require(Data(base64Encoded: fixture.base64))
        let image = try #require(JPEGDecoder.decodeRGB(jpeg))
        #expect(image.width == fixture.width)
        #expect(image.height == fixture.height)
        #expect(image.pixels.count == fixture.width * fixture.height * 3)
        #expect(sha256(image.pixels) == fixture.rgbSHA256)
    }

    @Test func fixturesCoverTheLayoutsThatMatter() {
        let names = Set(jpegFixtures.map(\.name))
        for required in ["baseline420", "baseline422Odd", "baseline444Odd", "baseline420Odd", "progressive420Odd"] {
            #expect(names.contains(required))
        }
        #expect(jpegFixtures.contains { $0.width % 2 == 1 && $0.height % 2 == 1 })
    }

    @Test(arguments: rejectedJPEGFixtures.map(\.name))
    func refusesWhatImageIOMustDecode(_ name: String) throws {
        let fixture = try #require(rejectedJPEGFixtures.first { $0.name == name })
        #expect(JPEGDecoder.decodeRGB(try #require(Data(base64Encoded: fixture.base64))) == nil)
    }

    @Test func refusesDataThatIsNotAJPEG() throws {
        #expect(JPEGDecoder.decodeRGB(Data()) == nil)
        #expect(JPEGDecoder.decodeRGB(Data("not a jpeg".utf8)) == nil)
        #expect(JPEGDecoder.decodeRGB(Data([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])) == nil)
        let fixture = try #require(jpegFixtures.first)
        let jpeg = try #require(Data(base64Encoded: fixture.base64))
        _ = JPEGDecoder.decodeRGB(jpeg.prefix(100))  // a cut file decodes or is refused, never crashes
        #expect(JPEGDecoder.decodeRGB(jpeg.prefix(20)) == nil)
    }
}

extension JPEGFixture: CustomTestStringConvertible {
    var testDescription: String { name }
}
